open class Subsystem(val name: String) {
    open fun status(): String {
        return "$name: OK"
    }
}

class IntakeSubsystem : Subsystem("Intake") {
    var hasPiece = false

    override fun status(): String {
        if (hasPiece) {
            return "Intake: holding game piece"
        } else {
            return "Intake: empty"
        }
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testInitialStatus() {
        val intake = IntakeSubsystem()
        Assert.assertEquals("Intake: empty", intake.status())
    }

    @Test
    fun testHoldingPiece() {
        val intake = IntakeSubsystem()
        intake.hasPiece = true
        Assert.assertEquals("Intake: holding game piece", intake.status())
    }

    @Test
    fun testInheritsName() {
        val intake = IntakeSubsystem()
        Assert.assertEquals("Intake", intake.name)
    }

    @Test
    fun testHasPieceStartsFalse() {
        val intake = IntakeSubsystem()
        Assert.assertFalse(intake.hasPiece)
    }
}
